#include "multi_gpu.h"
#include <iostream>

int main() {
    try {
        // Test with a simple case
        std::vector<int> devices = {0, 1};  // Use devices 0 and 1
        MultiResult result = gpu_asian_multi(100.0, 100.0, 0.05, 0.2, 1.0, 252, 1000000, 12345, devices);

        std::cout << "Price: " << result.price << std::endl;
        std::cout << "Std Error: " << result.std_error << std::endl;
        std::cout << "Paths per device: ";
        for (size_t i = 0; i < result.paths_per_device.size(); i++) {
            std::cout << result.paths_per_device[i] << " ";
        }
        std::cout << std::endl;

        return 0;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }
}
